scripts.prepare:
node -e "
const fs=require('fs');const p=require('path');
// Symlinks go into the profile's node_modules/@local/ (parent of the installed repo)
const profileNM = p.join(__dirname, '..');
const localDir = p.join(profileNM, '@local');
if (!fs.existsSync(localDir)) fs.mkdirSync(localDir, {recursive: true});
const plugins = fs.readdirSync(p.join(__dirname, 'plugins')).filter(f => {
  const pp = p.join(__dirname, 'plugins', f);
  return fs.statSync(pp).isDirectory();
});
plugins.forEach(plugin => {
  const link = p.join(localDir, plugin);
  const target = p.join(__dirname, 'plugins', plugin);
  try { fs.unlinkSync(link); } catch(e) {}
  fs.symlinkSync(target, link, 'dir');
  console.log('  @local/' + plugin + ' -> ' + target);
});
console.log('chrome-eye: prepared', plugins.length, 'plugin(s)');
"
